#!/usr/bin/env node
// Synthetic release contract, generated by the same compiled WASM as the web UI.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import * as glue from "../../rust/editor-runtime-wasm/pkg/opencut_editor_runtime_wasm_bg.js";

const bytes = await readFile(
	new URL(
		"../../rust/editor-runtime-wasm/pkg/opencut_editor_runtime_wasm_bg.wasm",
		import.meta.url,
	),
);
const { instance } = await WebAssembly.instantiate(bytes, {
	"./opencut_editor_runtime_wasm_bg.js": glue,
});
glue.__wbg_set_wasm(instance.exports);
instance.exports.__wbindgen_start();
const runtime = new glue.CanonicalEditorRuntime();
const projectId = "qa-release-policy-project";
const sourceText = "שלום לעולם";
const latinTransliteration = "Shalom la-olam";
const call = (id, input) => runtime.invokeSync(id, input, {}).result.data;
const revision = () => call("app.state.read", {}).value.revision;
const edit = (change) =>
	call("project.production.edit", {
		projectId,
		expectedRevision: revision(),
		change,
	});
try {
	const classic = JSON.parse(
		await readFile(
			new URL(
				"../../../crates/editor-api/tests/fixtures/classic-project.json",
				import.meta.url,
			),
			"utf8",
		),
	);
	classic.document.metadata.id = projectId;
	classic.document.metadata.name =
		"Synthetic release verification — no customer data";
	call("project.classic.session.attach", {
		projectId,
		expectedRevision: 0,
		classic,
	});
	edit({
		type: "importScript",
		rowIdPrefix: "release",
		sourceLanguage: "he",
		defaultDurationMs: 4000,
		text: `1\n00:00:00,000 --> 00:00:04,000\n${sourceText}\n\n2\n00:00:04,000 --> 00:00:08,000\nمرحبا بالعالم`,
	});
	edit({
		type: "editScriptRow",
		rowId: "release-1",
		expectedRowVersion: 1,
		content: {
			startMs: 0,
			endMs: 4000,
			sourceLanguage: "he",
			sourceText,
			latinTransliteration,
			visualDescription: "The synthetic presenter opens a door",
			speaker: "QA",
			timingEstimated: false,
		},
	});
	call("project.generative.edit", {
		projectId,
		expectedRevision: revision(),
		change: {
			type: "reference",
			reference: {
				id: "a".repeat(32),
				name: "synthetic.png",
				kind: "image",
				mime: "image/png",
				bytes: 17,
			},
		},
	});
	edit({
		type: "createReferenceSlot",
		slotId: "presenter",
		label: "Synthetic presenter",
	});
	edit({
		type: "addReferenceVersion",
		slotId: "presenter",
		expectedSlotVersion: 1,
		referenceId: "a".repeat(32),
		source: "uploaded",
	});
	edit({
		type: "approveReference",
		slotId: "presenter",
		expectedSlotVersion: 2,
		version: 1,
		approved: true,
	});
	call("project.production.handoff", {
		projectId,
		expectedRevision: revision(),
		handoffId: "release-handoff",
		request: "Preserve exact source and Latin pronunciation",
	});
	// Leave a redo boundary too, so all history encodings exercise both stacks.
	edit({
		type: "createReferenceSlot",
		slotId: "unused",
		label: "Undo/redo coverage",
	});
	call("history.undo", {});
	const extensions = call("app.state.read", {
		pointer: "/project/extensions",
	}).value;
	const archives = [
		{ name: "full", options: {} },
		{ name: "base", options: { compact: true } },
		{ name: "chained", options: { compact: true, chained: true } },
	].map(({ name, options }) => {
		const archive = call("project.classic.session.archive", {
			projectId,
			...options,
		});
		assert.equal(archive.schemaVersion, 6);
		assert.equal(archive.historyEncoding, name);
		assert.ok(archive.undoStack.length && archive.redoStack.length);
		assert.deepEqual(archive.classic.projectExtensions, extensions);
		return { name, archive };
	});
	await writeFile(
		new URL("session-policy-v6.fixture.json", import.meta.url),
		`${JSON.stringify(
			{
				description:
					"Synthetic schema-v6 production workspace; no real accounts, images or provider calls.",
				wasmSha256: createHash("sha256").update(bytes).digest("hex"),
				projectId,
				expected: {
					sourceText,
					latinTransliteration,
					referenceId: "a".repeat(32),
					handoffId: "release-handoff",
				},
				archives,
			},
			null,
			2,
		)}\n`,
	);
	console.log(
		"Generated schema-v6 full/base/chained production session fixture.",
	);
} finally {
	runtime.free();
}
